<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#f8fafc}*{box-sizing:border-box}body{margin:0;min-height:100vh;overflow:hidden;background:linear-gradient(125deg,#23395d,#365d92 55%,#a0b4d1);display:grid;place-items:center;padding:24px}.star{position:fixed;color:#ffffff2b;line-height:1;pointer-events:none;animation:float 9s ease-in-out infinite;text-shadow:0 0 35px #fff3}.s1{font-size:205px;top:5%;left:6%}.s2{font-size:82px;top:32%;left:30%;animation-delay:-3s}.s3{font-size:270px;right:-50px;bottom:2%;animation-delay:-5s}.s4{font-size:130px;right:15%;top:11%;animation-delay:-1s}.s5{font-size:57px;bottom:13%;left:17%;animation-delay:-7s}@keyframes float{50%{transform:translate(15px,-25px) rotate(11deg) scale(1.06)}}.shell{position:relative;width:min(100%,450px)}.glow{position:absolute;inset:14px -18px -18px;background:#23395d66;border-radius:34px;filter:blur(24px)}.card{position:relative;padding:38px;color:#f8fafc;background:#ffffff1c;border:1px solid #ffffff4d;border-radius:28px;box-shadow:0 28px 65px #0c1e3a59;backdrop-filter:blur(20px);animation:lift .7s ease-out}@keyframes lift{from{opacity:0;transform:translateY(26px) scale(.97)}to{opacity:1;transform:none}}.logo{text-align:center;margin-bottom:25px}.cap{width:66px;height:66px;display:grid;place-items:center;margin:auto;border-radius:20px;background:#ffffff1a;border:1px solid #ffffff3d;font-size:34px;box-shadow:inset 0 1px #fff5}.logo b{display:block;font-size:28px;letter-spacing:.4px;margin-top:12px}.logo p{font-size:13px;margin:6px;color:#e7effa}.welcome{margin:0;font-size:21px}.hint{margin:7px 0 20px;color:#e7effa;font-size:13px}.field{display:grid;gap:8px;margin:15px 0}label{font-size:13px;font-weight:700}input,select{width:100%;border:1px solid #ffffff33;border-radius:13px;padding:14px 15px;background:#fff;color:#334155;font:14px Inter;outline:0;transition:.2s}input:focus,select:focus{box-shadow:0 0 0 4px #ffffff2e;transform:translateY(-1px)}.hidden{display:none}.error{padding:11px;border-radius:11px;background:#fff0f0;color:#7f1d1d;font-size:13px}.submit{width:100%;margin-top:10px;border:1px solid #ffffff22;border-radius:13px;background:#23395d;color:#fff;padding:15px;font:700 15px Inter;cursor:pointer;box-shadow:0 9px 17px #172e4b66;transition:.2s}.submit:hover{transform:translateY(-2px);background:#1d3152}.note{font-size:12px;color:#e7effa}.footer{text-align:center;font-size:12px;color:#e6eef8;margin:23px 0 0}@media(max-width:480px){body{padding:17px}.card{padding:30px 24px}.s1{left:-70px}.s3{right:-120px}}</style></head><body><i class="star s1">✦</i><i class="star s2">✦</i><i class="star s3">✦</i><i class="star s4">✦</i><i class="star s5">✦</i><main class="shell"><i class="glow"></i><section class="card"><header class="logo"><div class="cap">🎓</div><b>FRExam</b><p>Sistem Ujian Berbasis Web</p></header><h1 class="welcome">Selamat Datang 👋</h1><p class="hint">Masuk untuk melanjutkan aktivitas belajar Anda.</p>@if($errors->any())<p class="error">{{ $errors->first() }}</p>@endif<form method="post" action="{{ route('login.store') }}">@csrf<div class="field"><label for="role">Masuk sebagai</label><select id="role" name="role" required><option value="" disabled selected>-- Pilih Peran --</option><option value="admin">Admin</option><option value="teacher">Guru</option><option value="student">Siswa</option></select></div><div class="field identity hidden"><label id="identity-label" for="identity"></label><input id="identity" autocomplete="username"></div><div class="field password hidden"><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password"></div><p class="hidden note" id="student-note">Token ujian dimasukkan dari Dashboard Siswa setelah login.</p><button class="submit" type="submit">Masuk ke FRExam →</button></form><p class="footer">© {{ date('Y') }} FRExam · Belajar dengan integritas</p></section></main><script>const role=document.querySelector('#role'),identity=document.querySelector('#identity'),label=document.querySelector('#identity-label'),identityBox=document.querySelector('.identity'),password=document.querySelector('.password'),note=document.querySelector('#student-note');role.addEventListener('change',()=>{const r=role.value,student=r==='student';identityBox.classList.remove('hidden');password.classList.remove('hidden');note.classList.toggle('hidden',!student);identity.name=student?'nisn':r==='teacher'?'nip':'username';identity.placeholder=student?'Masukkan NISN':r==='teacher'?'Masukkan NIP':'Masukkan username';label.textContent=student?'NISN':r==='teacher'?'NIP':'Username';identity.required=true})</script></body></html>
